<script lang="ts">
import Button from './Button.svelte';
let {label,value=$bindable(''),onChange,isReserved}:{label:string;value?:string;onChange?:(value:string)=>void;isReserved?:(shortcut:string,event:KeyboardEvent)=>boolean}=$props();
let recording=$state(false);let error=$state('');const id=$props.id();
function keys(e:KeyboardEvent){if(!recording)return;if(e.key==='Tab'){recording=false;return;}e.preventDefault();e.stopPropagation();if(e.key==='Escape'){recording=false;error='';return;}if(['Control','Meta','Shift','Alt'].includes(e.key))return;const k=e.key.length===1?e.key.toUpperCase():e.key;const chord=[e.ctrlKey?'Ctrl':'',e.metaKey?'Meta':'',e.altKey?'Alt':'',e.shiftKey?'Shift':'',k].filter(Boolean).join('+');const reserved=((e.ctrlKey||e.metaKey)&&['A','C','V','X','Z','Q','W','H','M'].includes(k))||(e.altKey&&k==='F4')||isReserved?.(chord,e);if(reserved){error='This shortcut is reserved. Choose another combination.';return;}if(!(e.ctrlKey||e.metaKey||e.altKey)){error='Include Control, Command, or Alt with your key.';return;}value=chord;onChange?.(value);recording=false;error='';}
</script>
<div class="od-stack"><div class="ka-between"><span id={id}>{label}</span><div class="ka-row"><Button variant="secondary" aria-labelledby={id} aria-describedby={`${id}-hint`} onkeydown={keys} onblur={()=>recording=false} onclick={()=>{recording=true;error='';}}>{recording?'Press keys…':value||'Set shortcut'}</Button><Button variant="ghost" disabled={!value} onclick={()=>{value='';onChange?.('');}}>Clear</Button></div></div><p id={`${id}-hint`} class="ka-help">{recording?'Press a combination. Escape cancels; Tab moves on.':'Select the shortcut to record a new combination.'}</p>{#if error}<p class="ka-error" role="alert">{error}</p>{/if}</div>
